package com.example.teminavigator.ui.mapimport android.content.res.Resourcesimport androidx.compose.foundation.Canvasimport androidx.compose.foundation.Imageimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.gestures.detectTapGesturesimport androidx.compose.foundation.gestures.detectTransformGesturesimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.BoxScopeimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Addimport androidx.compose.material.icons.filled.Removeimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.FloatingActionButtonimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialTheme.colorSchemeimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableFloatStateOfimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberUpdatedStateimport androidx.compose.runtime.setValueimport androidx.compose.runtime.snapshotFlowimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipToBoundsimport androidx.compose.ui.geometry.Offsetimport androidx.compose.ui.geometry.Sizeimport androidx.compose.ui.graphics.ImageBitmapimport androidx.compose.ui.graphics.graphicsLayerimport androidx.compose.ui.input.pointer.pointerInputimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.layout.onSizeChangedimport androidx.compose.ui.unit.dpimport com.example.teminavigator.domain.Destinationimport com.example.teminavigator.domain.RobotPoseimport com.example.teminavigator.ui.theme.locationBackgroundimport com.example.teminavigator.ui.theme.locationForegroundimport com.example.teminavigator.ui.theme.pinColorimport com.example.teminavigator.ui.theme.routeColorimport com.example.teminavigator.ui.theme.selectedPinColorimport kotlinx.coroutines.flow.filterNotNullimport kotlinx.coroutines.flow.first/** * Interactive floor map with zoom, pan, destination pins, the robot and an * optional route. * * Shows a loading indicator until [imageBitmap] is available. The user can * zoom by pinching or with the on-screen buttons (scale 1x to 5x, starting at * 1.5x) and pan by dragging. The map can't be moved past its edges. When * the map first appears it is centered on the robot, and afterward it follows * the robot so it stays inside the visible area. * * Drawing order, from back to front: map image, route, unselected pins, * selected pin (drawn larger), robot, zoom buttons, [overlay]. * * The same composable is used by several screens, which configure it through * the parameters (e.g. all pins and tappable on Home, one pin and not tappable * on Navigation). * * @param destinations Pins to draw. Destinations without a map position are skipped. * @param selectedId Id of the highlighted pin, or null for none. * @param robotPose Lambda returning the robot's current pose on the map, or null * if unknown. A lambda, not a value, so only the drawing is refreshed when * the pose changes and the caller is not recomposed. * @param path Route to draw, in map image pixels. Needs at least two points, * null means no route. * @param modifier Modifier for the map's root box. * @param onSelectDestination Called when the user taps a pin. If null, taps are * not handled at all and pins are not selectable. * @param imageBitmap The map image, or null while it is still loading. * @param overlay Screen-specific content, e.g. settings or accept buttons, * drawn on top of the map. Place it with `Modifier.align` inside the [BoxScope]. */@Composablefun InteractiveMap(    destinations: List<Destination>,    selectedId: String?,    robotPose: () -> RobotPose?,    path: List<Offset>?,    modifier: Modifier = Modifier,    onSelectDestination: ((Destination) -> Unit)? = null,    imageBitmap: ImageBitmap?,    overlay: @Composable BoxScope.() -> Unit = {}) {    // Colors are read here because the Canvas draw scope can't access the theme.    val robotPinBackground = colorScheme.locationBackground // colors to use in canvas    val robotPinForeground = colorScheme.locationForeground    val pinColor = colorScheme.pinColor    val selectedPinColor = colorScheme.selectedPinColor    val routeColor = colorScheme.routeColor    if (imageBitmap == null) {        Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {            CircularProgressIndicator() // wait for the map to load        }        return    }    // Zoom and pan state of the map: current zoom factor and shift in screen pixels.    var scale by remember { mutableFloatStateOf(1.5f) }    var offset by remember { mutableStateOf(Offset.Zero) }    val minScale = 1f    val maxScale = 5f    var boxSize by remember { mutableStateOf(Size.Zero) }    // always call the latest callback from inside pointerInput    val currentOnTap by rememberUpdatedState(onSelectDestination)    /*     * Centers the map on the robot once.     *     * Waits until the box has a size and the robot's first pose is known. Runs     * again if the box size or the bitmap changes, so it also re-centers after a     * resize.     */    LaunchedEffect(boxSize, imageBitmap) {        if (boxSize == Size.Zero) return@LaunchedEffect        val pose = snapshotFlow { robotPose() }.filterNotNull().first()        // robot position on screen at scale 1 / no offset        val base = imageToScreen(            Offset(pose.xPx, pose.yPx), boxSize,            imageBitmap.width, imageBitmap.height, 1f, Offset.Zero        )        val center = Offset(boxSize.width / 2f, boxSize.height / 2f)        // Shifting by (center - base) * scale centers the robot        offset = clampOffset(            (center - base) * scale, scale, boxSize,            imageBitmap.width, imageBitmap.height        )    }    /*     * Keeps the robot visible while it drives.     *     * On each pose change, checks how far the robot is from the edges of the     * box. If it is closer than a margin of 200dp, the map is shifted just     * enough to restore that distance, while still respecting the map's edges.     */    LaunchedEffect(boxSize, imageBitmap) {        if (boxSize == Size.Zero) return@LaunchedEffect        val margin = 200 * Resources.getSystem().displayMetrics.density// keep the robot at least this far from the edge        snapshotFlow { robotPose() }            .filterNotNull()            .collect { pose ->                val p = imageToScreen(                    Offset(pose.xPx, pose.yPx), boxSize,                    imageBitmap.width, imageBitmap.height, scale, offset                )                var dx = 0f                var dy = 0f                if (p.x < margin) dx = margin - p.x                else if (p.x > boxSize.width - margin) dx = boxSize.width - margin - p.x                if (p.y < margin) dy = margin - p.y                else if (p.y > boxSize.height - margin) dy = boxSize.height - margin - p.y                if (dx != 0f || dy != 0f) {                    offset = clampOffset(                        offset + Offset(dx, dy), scale, boxSize,                        imageBitmap.width, imageBitmap.height                    )                }            }    }    // Map area: measures its size, handles pinch/pan gestures and (optionally) pin taps.    Box(        modifier = modifier            .fillMaxSize()            .clipToBounds()            .onSizeChanged { boxSize = Size(it.width.toFloat(), it.height.toFloat()) }            .background(colorScheme.tertiary)            .pointerInput(Unit) {                detectTransformGestures { _, pan, zoom, _ ->                    val newScale = (scale * zoom).coerceIn(minScale, maxScale)                    scale = newScale                    offset = if (newScale == minScale) Offset.Zero                    else clampOffset(offset + pan, newScale, boxSize, imageBitmap.width, imageBitmap.height)                }            }            .then(                // tap handling only exists if the screen needs it                if (onSelectDestination != null) {                    /*                     * Pin selection: a tap selects the nearest pin within 32dp of its body, if any.                     * The pin position is recalculated for the current zoom and pan so it matches                     * what is drawn.                     */                    Modifier.pointerInput(destinations) {                        detectTapGestures { tap -> // tap on destination pin                            val hitRadius = 32.dp.toPx() // tap area                            val pinR = 14.dp.toPx()                            val hit = destinations                                .mapNotNull { destination ->                                    val p = destination.imagePx ?: return@mapNotNull null                                    // pin coordinates                                    val tip = imageToScreen(                                        p, boxSize,                                        imageBitmap.width,                                        imageBitmap.height,                                        scale,                                        offset                                    )                                    val body = Offset(tip.x, tip.y - pinR * 1.5f)                                    destination to (body - tap).getDistance()                                }                                .filter { it.second <= hitRadius } // filter out taps if too far away                                .minByOrNull { it.second }                                ?.first                            if (hit != null) currentOnTap?.invoke(hit)                        }                    }                } else Modifier            )    ) {        Image(            bitmap = imageBitmap,            contentDescription = "Floor map",            contentScale = ContentScale.Fit,            modifier = Modifier                .fillMaxSize()                .graphicsLayer {                    scaleX = scale; scaleY = scale                    translationX = offset.x; translationY = offset.y                }        )        // Overlay drawn on top of the map image: route, pins and robot.        Canvas(Modifier.fillMaxSize()) {            val pinR = 22.dp.toPx()            val width = imageBitmap.width            val height = imageBitmap.height            // internal redeclaration to pass less params (since most stay the same)            fun toScreen(p: Offset) = imageToScreen(                p, size, width, height, scale, offset            )            // draw the path            path?.takeIf { it.size >= 2 }?.let { pts ->                drawRoute(                    points = pts.map(::toScreen),                    color = routeColor,                    width = 16.dp.toPx()                )            }            // first draw unselected dest's, then selected            destinations.filter { it.id != selectedId }.forEach { destination ->                destination.imagePx?.let {                    drawPin(toScreen(it), pinColor, pinR)                }            }            destinations.find { it.id == selectedId }?.let { selDest ->                val tip = selDest.imagePx?.let(::toScreen) ?: return@let                drawPin(tip, selectedPinColor, pinR * 1.5f)            }            robotPose()?.let {                drawRobot(                    center = toScreen(Offset(it.xPx, it.yPx)),                    yawDeg = it.yawDeg,                    radius = pinR,                    pinBackground = robotPinBackground,                    pinForeground = robotPinForeground                )            }        }        // Zoom controls        Column(            modifier = Modifier                .align(Alignment.BottomEnd)                .padding(16.dp),            verticalArrangement = Arrangement.spacedBy(8.dp)        ) {            FloatingActionButton(                onClick = { scale = (scale + 0.3f).coerceIn(minScale, maxScale) },                modifier = Modifier                    .size(96.dp)            ) {                Icon(Icons.Default.Add, contentDescription = "Zoom in", Modifier.size(72.dp))            }            FloatingActionButton(                onClick = {                    scale = (scale - 0.3f).coerceIn(minScale, maxScale)                    if (scale == minScale) offset = Offset.Zero                },                modifier = Modifier                    .size(96.dp)            ) {                Icon(Icons.Default.Remove, contentDescription = "Zoom out", Modifier.size(72.dp))            }        }        // screen-specific buttons (e.g. settings, accept)        overlay()    }}/** * Limits the pan offset so the map can't be dragged past its edges. * * Takes into account how the image is fitted into the box and how large it is * at the current [scale]. On an axis where the scaled image is still smaller * than the box, no shift is allowed, so the image stays centered there. * * @param offset Wanted offset in screen pixels. * @param scale Current zoom factor. * @param box Size of the map area, in pixels. * @param imgW Width of the map bitmap, in pixels. * @param imgH Height of the map bitmap, in pixels. * @return The offset, limited to the allowed range. */private fun clampOffset(    offset: Offset, scale: Float, box: Size, imgW: Int, imgH: Int): Offset {    val fit = minOf(box.width / imgW, box.height / imgH)   // ContentScale.Fit factor    val maxX = maxOf(0f, (imgW * fit * scale - box.width) / 2f)    val maxY = maxOf(0f, (imgH * fit * scale - box.height) / 2f)    return Offset(offset.x.coerceIn(-maxX, maxX), offset.y.coerceIn(-maxY, maxY))}